<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\Payment;use Illuminate\Http\{RedirectResponse,Request};use Illuminate\Support\Facades\DB;use Inertia\{Inertia,Response};
class PaymentController extends Controller { public function index(Request $request):Response{$q=Payment::with('applicant:id,registration_number,full_name,payment_status')->latest();if($request->filled('status'))$q->where('status',$request->input('status'));if($request->filled('provider'))$q->where('provider',$request->input('provider'));return Inertia::render('Admin/Payments/Index',['payments'=>$q->paginate(25)->withQueryString()]);} public function verify(Request $request,Payment $payment):RedirectResponse{abort_unless($payment->provider==='manual',422);$data=$request->validate(['decision'=>['required','in:accept,reject'],'note'=>['nullable','string','max:1000','required_if:decision,reject']]);DB::transaction(function()use($request,$payment,$data){$payment=Payment::whereKey($payment->id)->lockForUpdate()->firstOrFail();$status=$data['decision']==='accept'?'paid':'failed';$payment->update(['status'=>$status,'paid_at'=>$status==='paid'?now():null,'verified_by'=>$request->user()->id,'verified_at'=>now(),'verification_note'=>$data['note']??null]);$payment->applicant()->update(['payment_status'=>$status,'paid_at'=>$status==='paid'?now():null]);DB::table('status_histories')->insert(['applicant_id'=>$payment->applicant_id,'dimension'=>'payment','from_status'=>'pending','to_status'=>$status,'note'=>$data['note']??'Verifikasi pembayaran manual','changed_by_type'=>'user','changed_by_id'=>$request->user()->id,'created_at'=>now()]);});return back()->with('success','Pembayaran manual diperbarui.');} }
